sys_variable_value.value:
(function execute(inputs, outputs) {
    var r = new x_doppe_doppel_t_0.DoppelIOCImport().updateAlertInDoppel(inputs.alert_id, {
        queue_state: inputs.queue_state,
        entity_state: inputs.entity_state,
        comment: inputs.comment,
        tag_action: inputs.tag_action,
        tag_name: inputs.tag_name
    });
    outputs.success = !!r.success;
    outputs.error = r.error || '';
    var a = r.data || {};
    outputs.queue_state = a.queue_state || '';
    outputs.entity_state = a.entity_state || '';
    outputs.doppel_link = a.doppel_link || '';
})(inputs, outputs);

